import assert from "node:assert/strict";

function exists(path: string): boolean {
  try {
    Deno.statSync(path);
    return true;
  } catch {
    return false;
  }
}

function escapeXml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

// The feeds are generated by `deno task build`, which CI runs before the tests.
const feedsBuilt = exists("dist/rss.xml") && exists("dist/feed.xml");

Deno.test("feeds exist, carry full post text, and pages carry autodiscovery links", () => {
  if (!feedsBuilt) {
    console.log("dist feeds missing; run `deno task build` first — skipping");
    return;
  }
  const rss = Deno.readTextFileSync("dist/rss.xml");
  const atom = Deno.readTextFileSync("dist/feed.xml");
  const index = Deno.readTextFileSync("dist/index.html");

  // Autodiscovery: both feed types announced in <head>.
  assert.match(index, /<link rel="alternate" type="application\/rss\+xml"[^>]*href="\/rss\.xml">/);
  assert.match(index, /<link rel="alternate" type="application\/atom\+xml"[^>]*href="\/feed\.xml">/);

  // Full text, not just the excerpt: every item/entry embeds the rendered body.
  const items = rss.match(/<item>/g) ?? [];
  const entries = atom.match(/<entry>/g) ?? [];
  assert.ok(items.length > 0, "rss.xml has items");
  assert.equal((rss.match(/<content:encoded>/g) ?? []).length, items.length);
  assert.equal((atom.match(/<content type="html">/g) ?? []).length, entries.length);
  assert.match(rss, /xmlns:content="http:\/\/purl\.org\/rss\/1\.0\/modules\/content\/"/);
  // The embedded content is rendered HTML (paragraphs), not a plain excerpt.
  assert.match(rss, /<content:encoded><!\[CDATA\[<div[\s\S]*?<p[\s>]/);
  assert.match(atom, /<content type="html">[\s\S]*?&lt;p[\s&]/);

  // A phrase from the end of a post body must appear in the Atom full text.
  const blogFiles = [...Deno.readDirSync("routes/blogs")]
    .filter((e) => e.isFile && e.name.endsWith(".md") && e.name !== "index.md")
    .map((e) => e.name)
    .sort();
  assert.ok(blogFiles.length > 0, "there are blog posts");
  const md = Deno.readTextFileSync(`routes/blogs/${blogFiles[0]}`);
  const body = md.replace(/^---\r?\n[\s\S]*?\r?\n---\r?\n/, "");
  const tailLine = body.split(/\n+/).map((l) => l.trim()).filter((l) =>
    l.length > 40 && !l.startsWith("#") && !l.startsWith("```")
  ).pop()!;
  const phrase = tailLine.replace(/[*`[\]]/g, "").replace(/\([^)]*\)/g, "").trim().slice(0, 40);
  assert.ok(
    atom.includes(escapeXml(phrase)) || atom.includes(phrase),
    `feed.xml contains a late-post phrase ("${phrase}…")`,
  );
});
